// Общие шаги для Payment Portal / отчёта Payments (#a83f47 View Details, #5e4fe6 итоги без Refunded; план specs/payments-portal.md).
// Окружение: Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение. Данные 17.11: 6 платежей ($149) + возвращённый JOB-0002 $2 (Refunded).
// Не сверено с сайтом при записи (правило проекта — тесты только пишутся): адрес /Payments (как в stripe-connect), подписи KPI —
// по скриншотам a83f47-details-*.png и 5e4fe6-v2-portal-desktop.png («Total Transactions», «Total Amount», «Refunds not included: $3 (2)»).
import { expect, Locator, Page } from '@playwright/test';
import { pp, ROLE } from '../pricebook/pricebook-helpers';

export { ROLE, pp };

export async function openPortal(page: Page) {
  await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
  await page.goto(pp('/paymentportal'));
  await expect(page.getByRole('heading', { name: 'Payment Portal' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText('Recent Transactions')).toBeVisible();
  await expect(page.getByRole('button', { name: 'View Details' }).first()).toBeVisible({ timeout: 30_000 });
}

/** Строки таблицы Recent Transactions (с кнопкой View Details). */
export const txRows = (page: Page): Locator =>
  page.getByRole('row').filter({ has: page.getByRole('button', { name: 'View Details' }) });

export const detailsDialog = (page: Page): Locator => page.getByRole('dialog').filter({ hasText: 'Payment details' });

export const parseMoney = (s: string): number => Number(s.replace(/[^0-9.\-]/g, ''));

/** Значение KPI по подписи («Total Transactions» → «6», «Total Amount» → «$149»). */
export async function kpi(page: Page, label: string): Promise<string> {
  const text = await page.locator('main').innerText();
  const m = text.match(new RegExp(`${label}\\s*\\n?\\s*(\\$?[\\d,]+(?:\\.\\d\\d)?)`));
  expect(m, `KPI «${label}» найден`).not.toBeNull();
  return m![1];
}
